import React, { useState, useEffect } from 'react';
import Modal from '../components/Modal';
import Calendar from '../components/Calendar';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
      <span style={{ color: '#f59e0b' }}>{'★'.repeat(Math.floor(v))}{'☆'.repeat(5 - Math.floor(v))}</span>
      <span style={{ color: 'var(--text2)', fontSize: '.82rem', fontWeight: 600 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function ModeBadge({ mode }) {
  const map = {
    en_ligne:   ['🌐', 'En ligne',             '#38bdf8', 'rgba(56,189,248,0.12)'],
    presentiel: ['🏫', 'Présentiel',           '#43e97b', 'rgba(67,233,123,0.12)'],
    les_deux:   ['🔀', 'En ligne & Présentiel', '#6c63ff', 'rgba(108,99,255,0.12)'],
  };
  const [icon, label, color, bg] = map[mode] || map.presentiel;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: '.73rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: bg, color }}>
      {icon} {label}
    </span>
  );
}

export default function ProfModal({ prof, onClose }) {
  const { user } = useAuth();
  const [tab, setTab]                           = useState('profil');
  const [avis, setAvis]                         = useState([]);
  const [dispos, setDispos]                     = useState([]);
  const [step, setStep]                         = useState(null);
  const [selectedDispo, setSelectedDispo]       = useState(null);
  const [modeChoisi, setModeChoisi]             = useState(null);
  const [notes, setNotes]                       = useState('');
  const [submitting, setSubmitting]             = useState(false);
  const [reservationFaite, setReservationFaite] = useState(null);

  const profId   = prof.prof_id || prof.id;
  const profMode = prof.mode_enseignement || 'presentiel';
  const profNom  = [prof.user_prenom, prof.user_nom || prof.nom].filter(Boolean).join(' ') || 'Professeur';

  useEffect(() => {
    if (tab === 'avis') {
      api.get(`/api/avis/professeur/${profId}`).then(r => setAvis(r.data)).catch(() => setAvis([]));
    }
    if (tab === 'calendrier' || step === 'choix_dispo') {
      api.get(`/api/professeurs/${profId}/disponibilites`).then(r => setDispos(r.data ?? [])).catch(() => setDispos([]));
    }
  }, [tab, step, profId]);

  const fmt = (str) => str
    ? new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
    : '';

  const modeInfo = (mode) => mode === 'en_ligne'
    ? { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.12)', border: 'rgba(56,189,248,0.35)' }
    : { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)', border: 'rgba(67,233,123,0.35)' };

  const getTarif = () => {
    const m = modeChoisi || (profMode !== 'les_deux' ? profMode : null);
    return m === 'en_ligne' ? prof.tarif_en_ligne : m === 'presentiel' ? prof.tarif_presentiel : null;
  };

  const disponibles = dispos.filter(d => d.nb_inscrits < d.nb_max_etudiants);

  const reserver = async () => {
    const mode = profMode === 'les_deux' ? modeChoisi : profMode;
    if (!mode) { alert('Choisissez un mode de cours'); return; }
    const modeEffectif = (selectedDispo.mode_seance && selectedDispo.mode_seance !== 'les_deux')
      ? selectedDispo.mode_seance : mode;
    setSubmitting(true);
    try {
      const res = await api.post('/api/reservations/', {
        prof_id: profId,
        disponibilite_id: selectedDispo.id,
        date_cours: selectedDispo.date_specifique,
        heure_debut: selectedDispo.heure_debut,
        heure_fin: selectedDispo.heure_fin,
        mode_seance: modeEffectif,
        notes_etudiant: notes,
      });
      setReservationFaite(res.data);
      setStep('confirmation');
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmitting(false);
    }
  };

  const btnStyle = (disabled) => ({
    width: '100%', padding: '13px', border: 'none', borderRadius: 12,
    fontWeight: 700, fontSize: '.92rem', cursor: disabled ? 'not-allowed' : 'pointer',
    background: disabled ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)',
    color: '#fff',
  });

  const card = { background: 'var(--surface2)', borderRadius: 14, padding: 16, marginBottom: 12 };

  /* ── CONFIRMATION ── */
  if (step === 'confirmation' && reservationFaite) {
    const mi = modeInfo(reservationFaite.mode_seance);
    return (
      <Modal onClose={onClose} maxWidth={500}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ width: 64, height: 64, borderRadius: '50%', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.8rem', margin: '0 auto 16px', boxShadow: '0 8px 24px rgba(67,233,123,0.3)' }}>
            🎉
          </div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.3rem', margin: '0 0 6px' }}>Réservation envoyée !</h2>
          <p style={{ color: 'var(--text2)', fontSize: '.85rem', margin: '0 0 20px' }}>En attente de confirmation par le professeur.</p>

          <div style={{ background: 'var(--surface2)', borderRadius: 14, padding: 18, textAlign: 'left', marginBottom: 14 }}>
            <div style={{ fontSize: '.7rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 12 }}>📋 Récapitulatif</div>
            {[['Professeur', profNom], ['Date', fmt(reservationFaite.date_cours)], ['Horaire', `${String(reservationFaite.heure_debut).slice(0,5)} → ${String(reservationFaite.heure_fin).slice(0,5)}`]].map(([k, v]) => (
              <div key={k} style={{ display: 'flex', justifyContent: 'space-between', padding: '7px 0', borderBottom: '1px solid var(--border)' }}>
                <span style={{ color: 'var(--text2)', fontSize: '.83rem' }}>{k}</span>
                <span style={{ fontWeight: 600, fontSize: '.83rem' }}>{v}</span>
              </div>
            ))}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '7px 0', borderBottom: '1px solid var(--border)' }}>
              <span style={{ color: 'var(--text2)', fontSize: '.83rem' }}>Mode</span>
              <span style={{ fontWeight: 700, color: mi.color, background: mi.bg, padding: '2px 10px', borderRadius: 20, fontSize: '.76rem' }}>{mi.icon} {mi.label}</span>
            </div>
            {reservationFaite.tarif_applique && (
              <div style={{ display: 'flex', justifyContent: 'space-between', padding: '7px 0' }}>
                <span style={{ color: 'var(--text2)', fontSize: '.83rem' }}>Tarif</span>
                <span style={{ fontWeight: 800, color: '#43e97b' }}>{reservationFaite.tarif_applique} DT/h</span>
              </div>
            )}
          </div>

          {reservationFaite.mode_seance === 'en_ligne' && reservationFaite.lien_meet && (
            <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.25)', borderRadius: 12, padding: 14, marginBottom: 14, textAlign: 'left' }}>
              <div style={{ fontWeight: 700, color: '#38bdf8', marginBottom: 8 }}>🎥 Lien Google Meet</div>
              <p style={{ fontSize: '.78rem', color: 'var(--text2)', marginBottom: 10 }}>Utilisez ce lien pour rejoindre le cours à l'heure prévue.</p>
              <a href={reservationFaite.lien_meet} target="_blank" rel="noreferrer"
                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, background: 'linear-gradient(135deg,#38bdf8,#0ea5e9)', color: '#fff', padding: '10px', borderRadius: 10, fontWeight: 700, textDecoration: 'none', marginBottom: 8 }}>
                📹 Rejoindre le Meet
              </a>
              <div style={{ padding: '6px 10px', background: 'var(--surface2)', borderRadius: 8, fontSize: '.72rem', color: 'var(--text2)', wordBreak: 'break-all', fontFamily: 'monospace' }}>
                {reservationFaite.lien_meet}
              </div>
            </div>
          )}

          <button onClick={onClose} style={btnStyle(false)}>Fermer</button>
        </div>
      </Modal>
    );
  }

  /* ── PRINCIPAL ── */
  return (
    <Modal onClose={onClose} maxWidth={700}>

      {/* En-tête */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 22, paddingBottom: 18, borderBottom: '1px solid var(--border)' }}>
        <div style={{ width: 68, height: 68, borderRadius: '50%', flexShrink: 0, background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.7rem', overflow: 'hidden', border: '3px solid var(--border)' }}>
          {prof.photo_url ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.2rem', marginBottom: 5 }}>{profNom}</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', marginBottom: 5 }}>
            {prof.ville && <span style={{ fontSize: '.8rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
            <ModeBadge mode={profMode} />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
            <Stars n={prof.note_moyenne} />
            <span style={{ fontSize: '.76rem', color: 'var(--text2)' }}>{prof.nb_avis} avis</span>
            {prof.tarif_en_ligne && <span style={{ fontSize: '.8rem', fontWeight: 700, color: '#38bdf8' }}>🌐 {prof.tarif_en_ligne} DT/h</span>}
            {prof.tarif_presentiel && <span style={{ fontSize: '.8rem', fontWeight: 700, color: '#43e97b' }}>🏫 {prof.tarif_presentiel} DT/h</span>}
          </div>
        </div>
        <button onClick={onClose} style={{ width: 34, height: 34, borderRadius: 9, flexShrink: 0, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', fontSize: '.95rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
      </div>

      {/* Onglets */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 22, gap: 4 }}>
        {[['profil','📋 Profil'],['calendrier','📅 Disponibilités'],['avis','⭐ Avis']].map(([t, l]) => (
          <div key={t} onClick={() => { setTab(t); setStep(null); setSelectedDispo(null); }}
            style={{ flex: 1, padding: '9px 6px', textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.84rem', transition: 'all .2s', background: tab === t ? '#6c63ff' : 'transparent', color: tab === t ? '#fff' : 'var(--text2)' }}>
            {l}
          </div>
        ))}
      </div>

      {/* ── Profil ── */}
      {tab === 'profil' && step === null && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {prof.bio && (
            <div style={card}>
              <div style={{ fontWeight: 700, marginBottom: 8, fontSize: '.88rem' }}>📝 À propos</div>
              <div style={{ fontSize: '.85rem', color: 'var(--text2)', lineHeight: 1.7 }}>{prof.bio}</div>
            </div>
          )}
          {prof.niveaux?.length > 0 && (
            <div style={card}>
              <div style={{ fontWeight: 700, marginBottom: 10, fontSize: '.88rem' }}>🎓 Niveaux enseignés</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                {prof.niveaux.map(n => (
                  <span key={n} style={{ background: 'rgba(108,99,255,0.12)', color: '#6c63ff', fontSize: '.78rem', fontWeight: 600, padding: '4px 12px', borderRadius: 20 }}>{n}</span>
                ))}
              </div>
            </div>
          )}
          {(prof.tarif_en_ligne || prof.tarif_presentiel) && (
            <div style={card}>
              <div style={{ fontWeight: 700, marginBottom: 12, fontSize: '.88rem' }}>💰 Tarifs horaires</div>
              <div style={{ display: 'flex', gap: 10 }}>
                {prof.tarif_en_ligne && (
                  <div style={{ flex: 1, padding: 14, textAlign: 'center', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 10 }}>
                    <div style={{ fontSize: '.76rem', color: '#38bdf8', marginBottom: 4 }}>🌐 En ligne</div>
                    <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#38bdf8', fontSize: '1.2rem' }}>{prof.tarif_en_ligne} DT</div>
                    <div style={{ fontSize: '.7rem', color: 'var(--text2)' }}>/ heure</div>
                  </div>
                )}
                {prof.tarif_presentiel && (
                  <div style={{ flex: 1, padding: 14, textAlign: 'center', background: 'rgba(67,233,123,0.08)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10 }}>
                    <div style={{ fontSize: '.76rem', color: '#43e97b', marginBottom: 4 }}>🏫 Présentiel</div>
                    <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#43e97b', fontSize: '1.2rem' }}>{prof.tarif_presentiel} DT</div>
                    <div style={{ fontSize: '.7rem', color: 'var(--text2)' }}>/ heure</div>
                  </div>
                )}
              </div>
            </div>
          )}
          {user?.role === 'étudiant' && (
            <button onClick={() => setStep('choix_dispo')} style={{ ...btnStyle(false), boxShadow: '0 4px 20px rgba(108,99,255,0.3)' }}>
              📅 Réserver un cours
            </button>
          )}
        </div>
      )}

      {/* ── Choix dispo ── */}
      {step === 'choix_dispo' && (
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 18 }}>
            <button onClick={() => { setStep(null); setSelectedDispo(null); setModeChoisi(null); }}
              style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 8, padding: '5px 12px', color: 'var(--text)', cursor: 'pointer', fontSize: '.82rem', fontWeight: 600 }}>
              ← Retour
            </button>
            <div>
              <div style={{ fontWeight: 700 }}>Choisir un créneau</div>
              <div style={{ fontSize: '.76rem', color: 'var(--text2)' }}>{disponibles.length} créneau{disponibles.length !== 1 ? 'x' : ''} disponible{disponibles.length !== 1 ? 's' : ''}</div>
            </div>
          </div>

          {disponibles.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '36px 20px', color: 'var(--text2)', background: 'var(--surface2)', borderRadius: 14 }}>
              <div style={{ fontSize: '2rem', marginBottom: 10 }}>📭</div>
              <div style={{ fontWeight: 700, marginBottom: 4 }}>Aucun créneau disponible</div>
              <div style={{ fontSize: '.82rem' }}>Ce professeur n'a pas encore publié de disponibilités.</div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 250, overflowY: 'auto', paddingRight: 4, marginBottom: 14 }}>
              {disponibles.map(d => {
                const mi  = modeInfo(d.mode_seance || profMode);
                const sel = selectedDispo?.id === d.id;
                const pl  = d.nb_max_etudiants - d.nb_inscrits;
                return (
                  <div key={d.id} onClick={() => { setSelectedDispo(d); setModeChoisi(null); }}
                    style={{ padding: '12px 14px', borderRadius: 12, cursor: 'pointer', border: sel ? '2px solid #6c63ff' : '2px solid var(--border)', background: sel ? 'rgba(108,99,255,0.08)' : 'var(--surface2)', transition: 'all .15s' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <div style={{ fontWeight: 700, marginBottom: 3, fontSize: '.88rem' }}>📆 {fmt(d.date_specifique)}</div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <span style={{ fontSize: '.83rem', color: 'var(--accent)', fontWeight: 600 }}>🕒 {d.heure_debut?.slice(0,5)} – {d.heure_fin?.slice(0,5)}</span>
                          <span style={{ fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: mi.bg, color: mi.color }}>{mi.icon} {mi.label}</span>
                        </div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div style={{ fontSize: '.76rem', fontWeight: 700, color: pl <= 1 ? '#f59e0b' : '#43e97b' }}>👥 {pl} place{pl > 1 ? 's' : ''}</div>
                        {sel && <div style={{ fontSize: '.68rem', color: '#6c63ff', fontWeight: 700, marginTop: 3 }}>✓ Sélectionné</div>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {selectedDispo && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {profMode === 'les_deux' && (
                <div>
                  <div style={{ fontSize: '.76rem', fontWeight: 700, color: 'var(--text2)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.07em' }}>Mode du cours</div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {[
                      { value: 'en_ligne',   icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.1)',  border: 'rgba(56,189,248,0.4)'  },
                      { value: 'presentiel', icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)',  border: 'rgba(67,233,123,0.4)'  },
                    ].map(m => (
                      <div key={m.value} onClick={() => setModeChoisi(m.value)}
                        style={{ padding: 12, borderRadius: 10, cursor: 'pointer', textAlign: 'center', border: modeChoisi === m.value ? `2px solid ${m.border}` : '2px solid var(--border)', background: modeChoisi === m.value ? m.bg : 'var(--surface2)', transition: 'all .15s' }}>
                        <div style={{ fontSize: '1.4rem', marginBottom: 4 }}>{m.icon}</div>
                        <div style={{ fontWeight: 700, fontSize: '.85rem', color: modeChoisi === m.value ? m.color : 'var(--text)' }}>{m.label}</div>
                        {m.value === 'en_ligne' && prof.tarif_en_ligne && <div style={{ fontSize: '.7rem', color: m.color, marginTop: 2 }}>{prof.tarif_en_ligne} DT/h</div>}
                        {m.value === 'presentiel' && prof.tarif_presentiel && <div style={{ fontSize: '.7rem', color: m.color, marginTop: 2 }}>{prof.tarif_presentiel} DT/h</div>}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {(profMode === 'en_ligne' || modeChoisi === 'en_ligne') && (
                <div style={{ padding: '9px 13px', background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 9, fontSize: '.78rem', color: '#38bdf8', display: 'flex', gap: 7 }}>
                  <span>🎥</span><span>Un lien Google Meet sera généré automatiquement lors de la confirmation.</span>
                </div>
              )}

              <textarea rows={2} value={notes} onChange={e => setNotes(e.target.value)}
                placeholder="Message pour le prof (optionnel)..."
                style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 9, color: 'var(--text)', padding: '9px 12px', width: '100%', outline: 'none', fontSize: '.86rem', resize: 'none', boxSizing: 'border-box' }}
              />

              <div style={{ background: 'rgba(108,99,255,0.07)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 10, padding: 12 }}>
                <div style={{ fontWeight: 700, color: '#6c63ff', marginBottom: 6, fontSize: '.8rem' }}>📋 Récapitulatif</div>
                <div style={{ fontSize: '.83rem', color: 'var(--text)', display: 'flex', flexDirection: 'column', gap: 3 }}>
                  <div>📆 {fmt(selectedDispo.date_specifique)}</div>
                  <div>🕒 {selectedDispo.heure_debut?.slice(0,5)} → {selectedDispo.heure_fin?.slice(0,5)}</div>
                  {getTarif() && <div>💰 {getTarif()} DT/h</div>}
                </div>
              </div>

              <button onClick={reserver} disabled={submitting || (profMode === 'les_deux' && !modeChoisi)}
                style={btnStyle(submitting || (profMode === 'les_deux' && !modeChoisi))}>
                {submitting ? '⏳ Envoi...' : '✅ Confirmer la réservation'}
              </button>
            </div>
          )}
        </div>
      )}

      {/* ── Calendrier ── */}
      {tab === 'calendrier' && (
        <div>
          <Calendar
            available={dispos.filter(d => d.nb_inscrits < d.nb_max_etudiants).map(d => new Date(d.date_specifique + 'T00:00:00').getDate())}
            booked={dispos.filter(d => d.nb_inscrits >= d.nb_max_etudiants).map(d => new Date(d.date_specifique + 'T00:00:00').getDate())}
          />
          <div style={{ marginTop: 12, display: 'flex', gap: 16, fontSize: '.76rem', color: 'var(--text2)' }}>
            <span><span style={{ color: '#43e97b' }}>■</span> Disponible</span>
            <span><span style={{ color: '#ff6584' }}>■</span> Complet</span>
          </div>
          {user?.role === 'étudiant' && (
            <button onClick={() => { setTab('profil'); setStep('choix_dispo'); }}
              style={{ marginTop: 14, ...btnStyle(false) }}>
              📅 Réserver ce professeur
            </button>
          )}
        </div>
      )}

      {/* ── Avis ── */}
      {tab === 'avis' && (
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 18, padding: 14, background: 'var(--surface2)', borderRadius: 12 }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontFamily: 'Syne', fontSize: '2.6rem', fontWeight: 800, lineHeight: 1 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</div>
              <Stars n={prof.note_moyenne} />
              <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 5 }}>{prof.nb_avis} avis</div>
            </div>
            <div style={{ flex: 1 }}>
              {[5,4,3,2,1].map(s => (
                <div key={s} style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 4 }}>
                  <span style={{ fontSize: '.7rem', color: 'var(--text2)', width: 16 }}>{s}★</span>
                  <div style={{ flex: 1, height: 5, background: 'var(--border)', borderRadius: 3, overflow: 'hidden' }}>
                    <div style={{ height: '100%', background: '#f59e0b', borderRadius: 3, width: `${s === 5 ? 70 : s === 4 ? 20 : s === 3 ? 7 : 2}%` }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
          {avis.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '28px 20px', color: 'var(--text2)', background: 'var(--surface2)', borderRadius: 12 }}>
              <div style={{ fontSize: '1.6rem', marginBottom: 7 }}>💬</div>
              Aucun avis pour ce professeur.
            </div>
          ) : avis.map(a => (
            <div key={a.id} style={{ background: 'var(--surface2)', borderRadius: 10, padding: 14, marginBottom: 9 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 5 }}>
                <div style={{ fontWeight: 700, fontSize: '.86rem' }}>{a.etudiant}</div>
                <div style={{ color: '#f59e0b', fontSize: '.86rem' }}>{'★'.repeat(a.note)}</div>
              </div>
              <div style={{ fontSize: '.83rem', color: 'var(--text2)', lineHeight: 1.6 }}>{a.commentaire}</div>
            </div>
          ))}
        </div>
      )}
    </Modal>
  );
}
